    {"code": "dk", "zh": "丹麦", "en": "Denmark", "continent": "欧洲", "capital": "哥本哈根", "area": "约4.3万平方公里", "population": "约590万（2024年估算）", "language": "丹麦语", "currency": "丹麦克朗（DKK）", "resources": ["北海石油", "天然气", "风力资源", "农产品"], "tourism": ["小美人鱼雕像：安徒生童话地标", "蒂沃利乐园：世界最古老游乐园之一", "新港：彩色房屋与运河风情"], "intro": "丹麦位于北欧日德兰半岛及众多岛屿之上，是连接北欧与欧洲大陆的桥梁。历史上维京人曾从这里扬帆远航，如今是著名的福利国家典范。风电产业全球领先，设计、乐高积木与安徒生童话文化影响深远。哥本哈根多次入选全球最宜居城市。"},
    {"code": "no", "zh": "挪威", "en": "Norway", "continent": "欧洲", "capital": "奥斯陆", "area": "约38.5万平方公里", "population": "约550万（2024年估算）", "language": "挪威语", "currency": "挪威克朗（NOK）", "resources": ["北海石油与天然气", "水力资源", "渔业", "森林"], "tourism": ["盖朗厄尔峡湾：世界遗产级峡湾风光", "布道石：悬崖绝壁俯瞰吕瑟峡湾", "维格兰雕塑公园：奥斯陆露天艺术殿堂"], "intro": "挪威位于北欧斯堪的纳维亚半岛西部，国土狭长，海岸线曲折，峡湾密布。北海石油与天然气使挪威跻身全球最富裕国家之列，主权财富基金规模居世界首位。渔业与航运业发达，三文鱼出口享誉全球。极光、午夜太阳与壮丽峡湾吸引着世界各地的旅行者。"},
    {"code": "se", "zh": "瑞典", "en": "Sweden", "continent": "欧洲", "capital": "斯德哥尔摩", "area": "约45万平方公里", "population": "约1050万（2024年估算）", "language": "瑞典语", "currency": "瑞典克朗（SEK）", "resources": ["铁矿", "森林", "水力资源", "铜矿"], "tourism": ["斯德哥尔摩老城：北欧保存最完好的中世纪城区之一", "瓦萨博物馆：展示17世纪沉船战舰", "阿比斯库国家公园：观测北极光的理想地点"], "intro": "瑞典位于北欧斯堪的纳维亚半岛东部，是北欧面积最大的国家，森林覆盖率约六成。铁矿资源丰富，工业实力雄厚，宜家、沃尔沃、爱立信等跨国公司闻名全球。高福利与社会平等著称，阿尔弗雷德·诺贝尔在此设立诺贝尔奖。斯德哥尔摩由十四座岛屿组成，被称为“北方威尼斯”。"},
    {"code": "fi", "zh": "芬兰", "en": "Finland", "continent": "欧洲", "capital": "赫尔辛基", "area": "约33.8万平方公里", "population": "约560万（2024年估算）", "language": "芬兰语、瑞典语", "currency": "欧元（EUR）", "resources": ["森林", "泥炭", "铜矿", "镍矿"], "tourism": ["赫尔辛基大教堂：白色地标，城市象征", "圣诞老人村（罗瓦涅米）：北极圈上的圣诞主题乐园", "芬兰堡：海上要塞，世界遗产"], "intro": "芬兰位于北欧，东与俄罗斯接壤，境内湖泊逾十八万个，被称为“千湖之国”。森林覆盖率约七成，造纸与林业产业发达，诺基亚曾引领全球移动通信时代。教育体系全球领先，多次被评为最幸福国家。桑拿文化、极光与圣诞老人是芬兰的独特名片。"},
    {"code": "is", "zh": "冰岛", "en": "Iceland", "continent": "欧洲", "capital": "雷克雅未克", "area": "约10.3万平方公里", "population": "约39万（2024年估算）", "language": "冰岛语", "currency": "冰岛克朗（ISK）", "resources": ["渔业", "地热资源", "水力资源", "硅藻土"], "tourism": ["蓝湖温泉：地热温泉胜地，乳蓝色湖水", "黄金圈：辛格维利尔裂谷、间歇泉与黄金瀑布", "杰古沙龙冰河湖：冰川浮冰与海豹"], "intro": "冰岛位于北大西洋，为欧洲最西端的岛国，地处美洲与欧亚板块交界，火山与冰川并存，被称为“冰与火之国”。经济曾长期依赖渔业，后转向金融与旅游业。地热资源极为丰富，首都雷克雅未克大量使用地热供暖。极光、冰川徒步与温泉体验吸引世界游客。"},
    {"code": "pl", "zh": "波兰", "en": "Poland", "continent": "欧洲", "capital": "华沙", "area": "约31.3万平方公里", "population": "约3700万（2024年估算）", "language": "波兰语", "currency": "兹罗提（PLN）", "resources": ["硬煤", "褐煤", "铜矿", "硫磺"], "tourism": ["华沙老城：战后重建的世界遗产", "维利奇卡盐矿：地下盐雕艺术博物馆", "克拉科夫瓦维尔城堡：王室古堡与教堂"], "intro": "波兰位于中欧，北临波罗的海，地处东西欧交通要冲。历史上屡遭列强瓜分，但民族与文化顽强延续，肖邦音乐与天主教传统深厚。1939年纳粹德国入侵波兰，第二次世界大战由此爆发。近年来经济快速增长，为欧盟重要成员国。华沙老城重建后仍被列入世界遗产。"},
    {"code": "cz", "zh": "捷克", "en": "Czechia", "continent": "欧洲", "capital": "布拉格", "area": "约7.9万平方公里", "population": "约1090万（2024年估算）", "language": "捷克语", "currency": "捷克克朗（CZK）", "resources": ["硬煤", "褐煤", "铀矿", "高岭土"], "tourism": ["查理大桥：布拉格地标，桥上雕像林立", "布拉格城堡：世界最大古城堡建筑群之一", "克鲁姆洛夫：中世纪小城，世界遗产"], "intro": "捷克位于中欧内陆，历史上为波希米亚王国核心，曾是神圣罗马帝国的重镇。1993年与斯洛伐克和平分立后成为独立国家。工业基础扎实，汽车与机械制造发达，啤酒文化与水晶玻璃制品闻名全球。首都布拉格保存着大量中世纪建筑，被誉为“百塔之城”。"},
    {"code": "sk", "zh": "斯洛伐克", "en": "Slovakia", "continent": "欧洲", "capital": "布拉迪斯拉发", "area": "约4.9万平方公里", "population": "约540万（2024年估算）", "language": "斯洛伐克语", "currency": "欧元（EUR）", "resources": ["褐煤", "铁矿", "铜矿", "森林"], "tourism": ["布拉迪斯拉发城堡：多瑙河畔的白色城堡", "斯皮什城堡：中欧最大城堡遗址之一", "塔特拉山：喀尔巴阡山脉最高峰，滑雪胜地"], "intro": "斯洛伐克位于中欧内陆，1993年与捷克和平分离后独立。喀尔巴阡山脉的塔特拉山纵贯北部，是冬季运动与徒步胜地。汽车工业发达，人均汽车产量居世界前列。首都布拉迪斯拉发与奥地利维也纳相距仅约六十公里，为欧洲距离最近的两个首都之一。"},
    {"code": "hu", "zh": "匈牙利", "en": "Hungary", "continent": "欧洲", "capital": "布达佩斯", "area": "约9.3万平方公里", "population": "约960万（2024年估算）", "language": "匈牙利语", "currency": "匈牙利福林（HUF）", "resources": ["铝土矿", "褐煤", "天然气", "地热资源"], "tourism": ["布达城堡：多瑙河畔的王室城堡，世界遗产", "匈牙利国会大厦：新哥特式建筑杰作", "塞切尼温泉浴场：欧洲最大药泉浴场之一"], "intro": "匈牙利位于中欧内陆，多瑙河纵贯全境，将首都布达佩斯分为布达与佩斯两部分。匈牙利语属乌拉尔语系，与周边语言迥异，文化独具一格。1956年事件与1989年开放奥匈边境，在欧洲历史上意义重大。温泉资源丰富，有“温泉之国”之称，国菜古拉什炖肉闻名。"},
    {"code": "ro", "zh": "罗马尼亚", "en": "Romania", "continent": "欧洲", "capital": "布加勒斯特", "area": "约23.8万平方公里", "population": "约1900万（2024年估算）", "language": "罗马尼亚语", "currency": "罗马尼亚列伊（RON）", "resources": ["石油", "天然气", "煤炭", "金矿"], "tourism": ["布朗城堡：传说中的“德古拉城堡”", "多瑙河三角洲：欧洲最大湿地，鸟类天堂", "锡吉什瓦拉：中世纪古城，世界遗产"], "intro": "罗马尼亚位于东南欧巴尔干半岛东北部，东临黑海，喀尔巴阡山脉呈弧形纵贯中部。历史上先后为达契亚王国与罗马帝国行省，罗马尼亚语属罗曼语族。石油工业发端较早，葡萄种植业历史悠久。特兰西瓦尼亚地区的古堡与吸血鬼传说闻名世界。"},
    {"code": "bg", "zh": "保加利亚", "en": "Bulgaria", "continent": "欧洲", "capital": "索非亚", "area": "约11.1万平方公里", "population": "约640万（2024年估算）", "language": "保加利亚语", "currency": "保加利亚列弗（BGN）", "resources": ["褐煤", "铜矿", "铅锌矿", "玫瑰油"], "tourism": ["里拉修道院：保加利亚精神圣地，世界遗产", "内塞伯尔古城：黑海之滨的千年古城", "亚历山大·涅夫斯基大教堂：巴尔干最大东正教堂之一"], "intro": "保加利亚位于东南欧巴尔干半岛东部，东临黑海，拥有悠久的色雷斯与拜占庭历史。保加利亚语使用西里尔字母，该国是西里尔字母的发源地之一。玫瑰谷盛产大马士革玫瑰，玫瑰油产量居世界前列，有“玫瑰之国”之称。酸奶与玫瑰制品是其特色名片。"},
    {"code": "rs", "zh": "塞尔维亚", "en": "Serbia", "continent": "欧洲", "capital": "贝尔格莱德", "area": "约8.8万平方公里", "population": "约660万（2024年估算）", "language": "塞尔维亚语", "currency": "塞尔维亚第纳尔（RSD）", "resources": ["铜矿", "煤炭", "铅锌矿", "石油（少量）"], "tourism": ["卡莱梅格丹城堡：贝尔格莱德古要塞，俯瞰多瑙河", "斯图代尼察修道院：中世纪塞尔维亚建筑杰作", "彼得罗瓦拉丁要塞：诺维萨德地标“多瑙河的直布罗陀”"], "intro": "塞尔维亚位于东南欧巴尔干半岛中部，曾为前南斯拉夫联盟的核心成员。首都贝尔格莱德地处萨瓦河与多瑙河交汇处，城市历史逾两千年。经济近年逐步恢复，基础设施建设加快。多瑙河风光、中世纪修道院与热情的音乐节文化吸引着游客。"},
    {"code": "hr", "zh": "克罗地亚", "en": "Croatia", "continent": "欧洲", "capital": "萨格勒布", "area": "约5.7万平方公里", "population": "约380万（2024年估算）", "language": "克罗地亚语", "currency": "欧元（EUR）", "resources": ["石油", "天然气", "铝土矿", "石灰岩"], "tourism": ["杜布罗夫尼克老城：亚得里亚海明珠，《权力的游戏》取景地", "普利特维采湖群国家公园：十六个湖泊层层相连", "戴克里先宫：斯普利特的古罗马宫殿遗址"], "intro": "克罗地亚位于东南欧，亚得里亚海沿岸，海岸线长达一千七百余公里，岛屿星罗棋布。2013年加入欧盟，2023年成为欧元区与申根区成员国。旅游业为经济支柱之一，杜布罗夫尼克因影视取景而名声大噪。喀斯特地貌与地中海气候造就了独特的山海风光。"},
    {"code": "si", "zh": "斯洛文尼亚", "en": "Slovenia", "continent": "欧洲", "capital": "卢布尔雅那", "area": "约2万平方公里", "population": "约210万（2024年估算）", "language": "斯洛文尼亚语", "currency": "欧元（EUR）", "resources": ["褐煤", "铅锌矿", "森林", "水力资源"], "tourism": ["布莱德湖：阿尔卑斯山麓的湖心岛教堂", "波斯托伊纳溶洞：欧洲著名喀斯特溶洞", "卢布尔雅那城堡：俯瞰首都老城"], "intro": "斯洛文尼亚位于中欧南部，西邻意大利，南接克罗地亚，是阿尔卑斯山麓的绿色小国。1991年从前南斯拉夫独立，为前南各国中经济最发达者，2004年加入欧盟与北约。森林覆盖率约六成，湖光山色优美。首都卢布尔雅那以小巧宜居闻名，龙桥是城市象征。"},
    {"code": "ba", "zh": "波黑", "en": "Bosnia and Herzegovina", "continent": "欧洲", "capital": "萨拉热窝", "area": "约5.1万平方公里", "population": "约320万（2024年估算）", "language": "波斯尼亚语、克罗地亚语、塞尔维亚语", "currency": "可兑换马克（BAM）", "resources": ["褐煤", "铁矿", "铝土矿", "木材"], "tourism": ["莫斯塔尔古桥：奥斯曼石拱桥，世界遗产", "萨拉热窝老城：东西方文化交汇之地", "布纳泉：喀斯特涌泉与修道院"], "intro": "波黑全称波斯尼亚和黑塞哥维那，位于巴尔干半岛西部，1992年从前南斯拉夫独立。首都萨拉热窝曾是一战导火索“萨拉热窝事件”的发生地。境内波斯尼亚、塞尔维亚与克罗地亚三族共处，实行民族分权制度。莫斯塔尔古桥是奥斯曼时期的建筑杰作，列入世界遗产。"},
    {"code": "me", "zh": "黑山", "en": "Montenegro", "continent": "欧洲", "capital": "波德戈里察", "area": "约1.4万平方公里", "population": "约62万（2024年估算）", "language": "黑山语", "currency": "欧元（EUR）", "resources": ["铝土矿", "铅锌矿", "森林", "水力资源"], "tourism": ["科托尔湾：峡湾般的地中海海湾，世界遗产", "布德瓦老城：亚得里亚海滨古城", "杜米托尔国家公园：黑湖与塔拉峡谷"], "intro": "黑山位于巴尔干半岛西南部，亚得里亚海东岸，2006年与塞尔维亚和平分立后独立。国名意为“黑色的山”，山地约占国土大部分，山海相依。科托尔湾被列为世界自然与文化双遗产，旅游业为经济支柱。2008年单方面采用欧元，2017年加入北约。"},
    {"code": "mk", "zh": "北马其顿", "en": "North Macedonia", "continent": "欧洲", "capital": "斯科普里", "area": "约2.6万平方公里", "population": "约180万（2024年估算）", "language": "马其顿语", "currency": "马其顿第纳尔（MKD）", "resources": ["铬矿", "铅锌矿", "煤炭", "森林"], "tourism": ["奥赫里德湖：欧洲最古老湖泊之一，湖畔世界遗产古城", "斯科普里石桥：首都地标", "马特卡峡谷：特雷斯卡河峡谷风光"], "intro": "北马其顿位于巴尔干半岛中部的内陆国，2019年由“马其顿”更名为“北马其顿”。历史上是古马其顿王国的故地，亚历山大大帝故乡。奥赫里德湖为欧洲最古老湖泊之一，湖畔古城与修道院列入世界遗产。首都斯科普里在1963年大地震后重建，横跨瓦尔达尔河。"},
    {"code": "al", "zh": "阿尔巴尼亚", "en": "Albania", "continent": "欧洲", "capital": "地拉那", "area": "约2.9万平方公里", "population": "约280万（2024年估算）", "language": "阿尔巴尼亚语", "currency": "阿尔巴尼亚列克（ALL）", "resources": ["铬矿", "铜矿", "石油", "天然气"], "tourism": ["培拉特古城：奥斯曼风格“千窗之城”，世界遗产", "布特林特考古遗址：古希腊罗马遗迹", "吉诺卡斯特古城：山城石屋，世界遗产"], "intro": "阿尔巴尼亚位于巴尔干半岛西南部，西临亚得里亚海与爱奥尼亚海，与意大利隔海相望。历史上长期处于奥斯曼帝国统治之下，1912年独立。曾长期奉行封闭政策，1990年代后逐步开放。铬矿资源丰富，海滨旅游近年快速发展。培拉特与吉诺卡斯特古城列入世界遗产。"},
    {"code": "gr", "zh": "希腊", "en": "Greece", "continent": "欧洲", "capital": "雅典", "area": "约13.2万平方公里", "population": "约1040万（2024年估算）", "language": "希腊语", "currency": "欧元（EUR）", "resources": ["铝土矿", "褐煤", "大理石", "铬矿"], "tourism": ["雅典卫城：帕特农神庙等古希腊文明象征", "圣托里尼岛：蓝顶教堂与火山海景", "德尔斐遗址：古希腊“世界肚脐”神谕圣地"], "intro": "希腊位于欧洲东南部巴尔干半岛南端，岛屿星罗棋布于爱琴海。这里是西方文明发源地，民主、哲学与奥林匹克运动皆源于此。航运业规模居世界前列，旅游为经济支柱之一。碧海蓝天与白色建筑交相辉映，圣托里尼等海岛享誉世界。"},
    {"code": "mt", "zh": "马耳他", "en": "Malta", "continent": "欧洲", "capital": "瓦莱塔", "area": "约316平方公里", "population": "约54万（2024年估算）", "language": "马耳他语、英语", "currency": "欧元（EUR）", "resources": ["石灰岩", "海盐", "海洋渔业"], "tourism": ["瓦莱塔古城：圣约翰骑士团建造的巴洛克名城，世界遗产", "姆迪纳古城：中世纪“静城”，电影取景地", "蓝洞与科米诺岛：地中海著名潜水与海景观光地"], "intro": "马耳他位于地中海中部，由主岛及戈佐、科米诺等岛屿组成，扼守欧非航路要冲。历史上先后受腓尼基、罗马、圣约翰骑士团与英国统治，1964年独立。瓦莱塔为世界遗产城市，骑士团时期建筑保存完好。气候温暖，历史遗迹密集，是热门度假目的地。"},
    {"code": "ee", "zh": "爱沙尼亚", "en": "Estonia", "continent": "欧洲", "capital": "塔林", "area": "约4.5万平方公里", "population": "约140万（2024年估算）", "language": "爱沙尼亚语", "currency": "欧元（EUR）", "resources": ["油页岩", "泥炭", "森林", "磷矿"], "tourism": ["塔林老城：保存完好的中世纪城市，世界遗产", "卡德里奥宫：彼得大帝夏宫园林", "帕尔努：波罗的海海滨度假胜地"], "intro": "爱沙尼亚位于波罗的海东岸，北临芬兰湾，与芬兰隔海相望，1991年从苏联独立。油页岩资源丰富，发电长期依赖页岩能源。数字政务全球领先，公民可在网上完成绝大多数政务服务，被誉为“电子国家”。塔林老城保留着完整的中世纪风貌，列入世界遗产。"},
    {"code": "lv", "zh": "拉脱维亚", "en": "Latvia", "continent": "欧洲", "capital": "里加", "area": "约6.5万平方公里", "population": "约190万（2024年估算）", "language": "拉脱维亚语", "currency": "欧元（EUR）", "resources": ["泥炭", "木材", "森林", "农产品"], "tourism": ["里加老城：新艺术运动建筑荟萃，世界遗产", "尤尔马拉：绵长沙滩与木屋别墅的海滨胜地", "伦代尔宫：巴洛克宫廷建筑杰作"], "intro": "拉脱维亚位于波罗的海东岸，1991年从苏联独立，2004年加入欧盟与北约。首都里加以新艺术运动建筑著称，老城列入世界遗产。森林覆盖率约五成，木材加工与港口物流为重要产业。尤尔马拉的白沙滩是波罗的海著名度假地，民族歌谣节传统悠久。"},
    {"code": "lt", "zh": "立陶宛", "en": "Lithuania", "continent": "欧洲", "capital": "维尔纽斯", "area": "约6.5万平方公里", "population": "约290万（2024年估算）", "language": "立陶宛语", "currency": "欧元（EUR）", "resources": ["琥珀", "泥炭", "木材", "农产品"], "tourism": ["维尔纽斯老城：欧洲最大中世纪古城之一，世界遗产", "特拉凯城堡：湖心岛上的红砖城堡", "库洛尼亚沙嘴：沙丘与渔村，世界遗产"], "intro": "立陶宛位于波罗的海东岸，为波罗的海三国中面积最大、人口最多的国家，1990年率先从苏联独立。历史上曾建立中欧大国立陶宛大公国，疆域一度东达黑海。维尔纽斯老城是欧洲最大的中世纪古城之一。波罗的海琥珀产量居世界前列，被誉为“琥珀之国”。"},
